        <div class="meta">
            <div class="meta-card"><span>Effective and last updated</span><strong>July 28, 2026</strong></div>
            <div class="meta-card"><span>Service contact</span><a href="mailto:support@educoreng.online?subject=Terms%20Enquiry">support@educoreng.online</a></div>
